interface CreateUser {
  name: string;
  email?: string;
}

const a: CreateUser = { name: "Ada" };
const b: CreateUser = { name: "Bob", email: "bob@example.com" };

function sendEmail(u: CreateUser) {
  if (u.email !== undefined) {
    console.log(u.email.toUpperCase());
  }
}

