interface User {
  id: string;
  name: string;
  bio?: string;
}

function applyPatch(user: User, patch: Partial<User>): User {
  return { ...user, ...patch };
}

applyPatch(user, { bio: "Engineer" }); // only bio updated

interface Profile { nickname?: string; }

function display(p: Profile) {
  return p.nickname.toUpperCase(); // runtime error if key missing
}

const fromApi: Profile = JSON.parse('{"nickname":null}');
display(fromApi); // null.toUpperCase() throws
